## Redis Configuration Bean

```java
@Configuration
public class RedisConfig {
    @Bean
    public RedisTemplate<String, Object> redisTemplate(RedisConnectionFactory factory) {
        RedisTemplate<String, Object> template = new RedisTemplate<>();
        template.setConnectionFactory(factory);
        template.setKeySerializer(new StringRedisSerializer());
        template.setValueSerializer(new GenericJackson2JsonRedisSerializer());
        template.setHashKeySerializer(new StringRedisSerializer());
        template.setHashValueSerializer(new GenericJackson2JsonRedisSerializer());
        return template;
    }
}
```

## String Operations

```java
@Service
public class CacheService {
    @Autowired private RedisTemplate<String, Object> redis;

    // Cache with TTL
    public void cacheProduct(Long id, ProductDTO product) {
        String key = "product:" + id;
        redis.opsForValue().set(key, product, Duration.ofMinutes(10));
    }

    public ProductDTO getCachedProduct(Long id) {
        return (ProductDTO) redis.opsForValue().get("product:" + id);
    }

    // Atomic counter for rate limiting
    public long incrementAndCheckRateLimit(String userId, int limitPerHour) {
        String key = "ratelimit:" + userId + ":" + LocalDateTime.now().getHour();
        Long count = redis.opsForValue().increment(key);
        if (count == 1) {
            redis.expire(key, Duration.ofHours(1));  // set TTL on first increment
        }
        return count;
    }
}
```

## Hash Operations

```java
// Store user session as hash — field-level operations
public void createSession(String sessionId, User user) {
    String key = "session:" + sessionId;
    Map<String, Object> sessionData = new HashMap<>();
    sessionData.put("userId", user.getId());
    sessionData.put("email", user.getEmail());
    sessionData.put("role", user.getRole());
    sessionData.put("createdAt", Instant.now().toString());
    sessionData.put("lastActivity", Instant.now().toString());

    redis.opsForHash().putAll(key, sessionData);
    redis.expire(key, Duration.ofHours(24));
}

public void updateLastActivity(String sessionId) {
    // Update one field without reading entire hash
    redis.opsForHash().put(
        "session:" + sessionId,
        "lastActivity",
        Instant.now().toString()
    );
    redis.expire("session:" + sessionId, Duration.ofHours(24));  // reset TTL
}

public Map<Object, Object> getSession(String sessionId) {
    return redis.opsForHash().entries("session:" + sessionId);
}
```

## TTL Management

```java
// Check remaining TTL
Long ttlSeconds = redis.getExpire("session:xyz", TimeUnit.SECONDS);
if (ttlSeconds != null && ttlSeconds < 300) {
    redis.expire("session:xyz", Duration.ofHours(1));  // extend session
}

// SETNX — only set if key doesn't exist (basis of distributed lock)
Boolean acquired = redis.opsForValue()
    .setIfAbsent("lock:job:cleanup", "owner-id", Duration.ofSeconds(30));
if (Boolean.TRUE.equals(acquired)) {
    try { runCleanup(); }
    finally { redis.delete("lock:job:cleanup"); }
}
```

## Lists — Queue and Activity Feed

```java
// Simple task queue
public void enqueueTask(Task task) {
    redis.opsForList().rightPush("queue:email", task);
}

// Consumer: blocking pop waits up to 5s for a message
public Task consumeTask() {
    return (Task) redis.opsForList().leftPop("queue:email", Duration.ofSeconds(5));
}

// Recent activity feed — keep last 100 items
public void recordActivity(String userId, Activity activity) {
    String key = "activity:" + userId;
    redis.opsForList().leftPush(key, activity);   // newest at left
    redis.opsForList().trim(key, 0, 99);          // keep only 100 newest
}

public List<Activity> getRecentActivity(String userId, int count) {
    return (List) redis.opsForList().range("activity:" + userId, 0, count - 1);
}
```

## Sets — Unique Membership

```java
// Daily unique visitors
public void recordVisit(String userId) {
    String key = "visitors:" + LocalDate.now();
    redis.opsForSet().add(key, userId);
    redis.expire(key, Duration.ofDays(7));  // keep 7 days
}

public Long getUniqueVisitorCount() {
    return redis.opsForSet().size("visitors:" + LocalDate.now());
}

// Set operations
public Set<Object> getCommonFans(String artist1, String artist2) {
    return redis.opsForSet().intersect("fans:" + artist1, "fans:" + artist2);
}
```

## Sorted Sets — Leaderboard

```java
// Game leaderboard
public void updateScore(String playerId, double score) {
    redis.opsForZSet().add("leaderboard:global", playerId, score);
}

public void addToScore(String playerId, double points) {
    redis.opsForZSet().incrementScore("leaderboard:global", playerId, points);
}

public List<String> getTopPlayers(int topN) {
    Set<Object> top = redis.opsForZSet()
        .reverseRange("leaderboard:global", 0, topN - 1);
    return top.stream().map(Object::toString).toList();
}

public Long getPlayerRank(String playerId) {
    Long rank = redis.opsForZSet().reverseRank("leaderboard:global", playerId);
    return rank != null ? rank + 1 : null;  // 1-indexed rank
}

// Time-windowed rate limiting with sorted set
public boolean checkRateLimit(String userId, int maxRequests, long windowMs) {
    String key = "ratelimit:sliding:" + userId;
    long now = System.currentTimeMillis();
    long windowStart = now - windowMs;

    // Remove old requests outside window
    redis.opsForZSet().removeRangeByScore(key, 0, windowStart);
    // Count requests in window
    Long count = redis.opsForZSet().zCard(key);
    if (count != null && count >= maxRequests) return false;
    // Add current request
    redis.opsForZSet().add(key, UUID.randomUUID().toString(), now);
    redis.expire(key, Duration.ofMillis(windowMs));
    return true;
}
```

## Manual Distributed Lock

```java
@Service
public class DistributedLockService {
    @Autowired private StringRedisTemplate redis;

    // Lua script for atomic check-and-delete
    private static final RedisScript<Long> RELEASE_SCRIPT = RedisScript.of(
        "if redis.call('get', KEYS[1]) == ARGV[1] then " +
        "  return redis.call('del', KEYS[1]) " +
        "else " +
        "  return 0 " +
        "end",
        Long.class
    );

    public String acquireLock(String lockName, Duration ttl) {
        String lockKey = "lock:" + lockName;
        String lockValue = UUID.randomUUID().toString();  // unique per holder

        Boolean acquired = redis.opsForValue()
            .setIfAbsent(lockKey, lockValue, ttl);  // SET NX PX — atomic

        return Boolean.TRUE.equals(acquired) ? lockValue : null;
    }

    public boolean releaseLock(String lockName, String lockValue) {
        String lockKey = "lock:" + lockName;
        Long result = redis.execute(RELEASE_SCRIPT,
            List.of(lockKey), lockValue);  // atomic check-and-delete
        return Long.valueOf(1L).equals(result);
    }

    public <T> T executeWithLock(String lockName, Duration ttl,
                                  Duration waitTimeout, Supplier<T> action) {
        String lockValue = null;
        long deadline = System.currentTimeMillis() + waitTimeout.toMillis();

        while (lockValue == null && System.currentTimeMillis() < deadline) {
            lockValue = acquireLock(lockName, ttl);
            if (lockValue == null) {
                try { Thread.sleep(50); } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                    throw new RuntimeException("Interrupted waiting for lock");
                }
            }
        }
        if (lockValue == null) throw new LockAcquisitionException("Could not acquire lock: " + lockName);

        try {
            return action.get();
        } finally {
            releaseLock(lockName, lockValue);
        }
    }
}

// Usage
public void processInventory(Long productId) {
    lockService.executeWithLock(
        "inventory:" + productId,
        Duration.ofSeconds(30),  // lock TTL
        Duration.ofSeconds(5),   // wait timeout
        () -> { doInventoryUpdate(productId); return null; }
    );
}
```

## Redisson — Battle-Tested Lock

```java
@Configuration
public class RedissonConfig {
    @Bean
    public RedissonClient redissonClient() {
        Config config = new Config();
        config.useSingleServer().setAddress("redis://localhost:6379");
        return Redisson.create(config);
    }
}

@Service
public class InventoryService {
    @Autowired RedissonClient redisson;

    public void updateInventory(Long productId, int delta) {
        RLock lock = redisson.getLock("inventory:" + productId);
        try {
            lock.lock(30, TimeUnit.SECONDS);  // auto-renewal if taking longer
            doInventoryUpdate(productId, delta);
        } finally {
            lock.unlock();
        }
    }
}
// Redisson handles: lock renewal, re-entrant locking, fair locking, Redlock
```

## Spring Cache Abstraction

```java
@Service
@CacheConfig(cacheNames = "products")
public class ProductService {

    // @Cacheable: check cache first, call method on miss
    @Cacheable(key = "#id")
    public ProductDTO getProduct(Long id) {
        return productRepo.findById(id)
            .map(mapper::toDTO)
            .orElseThrow(() -> new ProductNotFoundException(id));
        // Result cached with key "products::5" (for id=5)
    }

    // @CachePut: always call method, update cache with result
    @CachePut(key = "#product.id")
    public ProductDTO updateProduct(ProductDTO product) {
        Product saved = productRepo.save(mapper.toEntity(product));
        return mapper.toDTO(saved);
    }

    // @CacheEvict: remove from cache after method executes
    @CacheEvict(key = "#id")
    public void deleteProduct(Long id) {
        productRepo.deleteById(id);
    }

    // Evict all — for bulk operations
    @CacheEvict(allEntries = true)
    public void clearProductCache() {}
}
```

