## Cache Stampede Prevention

```java
// Pattern: single-flight — only one DB call for concurrent misses
@Service
public class ProductCacheService {
    @Autowired RedisTemplate<String, Object> redis;
    @Autowired StringRedisTemplate stringRedis;
    @Autowired ProductRepository repo;

    public ProductDTO getProduct(Long id) {
        String key = "product:" + id;
        ProductDTO cached = (ProductDTO) redis.opsForValue().get(key);
        if (cached != null) return cached;

        // Acquire short lock to prevent stampede
        String lockKey = "lock:product:" + id;
        Boolean locked = stringRedis.opsForValue()
            .setIfAbsent(lockKey, "1", Duration.ofSeconds(5));

        if (Boolean.TRUE.equals(locked)) {
            try {
                ProductDTO dto = repo.findById(id).map(mapper::toDTO).orElseThrow();
                redis.opsForValue().set(key, dto, Duration.ofMinutes(10));
                return dto;
            } finally {
                stringRedis.delete(lockKey);
            }
        } else {
            // Another thread is loading — wait briefly and retry
            try { Thread.sleep(100); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
            return getProduct(id);  // retry — cache should be warm now
        }
    }
}
```
